input.proposed_solution:
Add a `newCheckout` flag read from FLAG_NEW_CHECKOUT with the existing parseBool helper, defaulting to false. checkoutPage() renders checkout-v2 only when the flag is on. Tests cover the default, enabling it, and template selection.

Patch (already applied in the repository snapshot):
```diff
--- a/src/checkout.js
+++ b/src/checkout.js
@@ -1,9 +1,9 @@
 // @ts-check

 /**
- * @param {import("./flags.js").Flags} _flags
+ * @param {import("./flags.js").Flags} flags
  * @param {{ items: number }} cart
  */
-export function checkoutPage(_flags, cart) {
-  return { template: "checkout-v1", items: cart.items };
+export function checkoutPage(flags, cart) {
+  return { template: flags.newCheckout ? "checkout-v2" : "checkout-v1", items: cart.items };
 }
--- a/src/flags.js
+++ b/src/flags.js
@@ -1,13 +1,16 @@
 // @ts-check

-/** @typedef {{ searchV2: boolean }} Flags */
+/** @typedef {{ searchV2: boolean, newCheckout: boolean }} Flags */

 /**
  * @param {Record<string, string | undefined>} env
  * @returns {Flags}
  */
 export function loadFlags(env) {
-  return { searchV2: parseBool(env.FLAG_SEARCH_V2, false) };
+  return {
+    searchV2: parseBool(env.FLAG_SEARCH_V2, false),
+    newCheckout: parseBool(env.FLAG_NEW_CHECKOUT, false),
+  };
 }

 /**
--- /dev/null
+++ b/test/checkout.test.js
@@ -0,0 +1,8 @@
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { checkoutPage } from "../src/checkout.js";
+
+test("v1 by default, v2 behind the flag", () => {
+  assert.equal(checkoutPage({ searchV2: false, newCheckout: false }, { items: 1 }).template, "checkout-v1");
+  assert.equal(checkoutPage({ searchV2: false, newCheckout: true }, { items: 1 }).template, "checkout-v2");
+});
--- a/test/flags.test.js
+++ b/test/flags.test.js
@@ -2,9 +2,11 @@
 import assert from "node:assert/strict";
 import { loadFlags, parseBool } from "../src/flags.js";

-test("flags default to off", () => assert.deepEqual(loadFlags({}), { searchV2: false }));
+test("flags default to off", () => assert.deepEqual(loadFlags({}), { searchV2: false, newCheckout: false }));
 test("parseBool", () => {
   assert.equal(parseBool("TRUE", false), true);
   assert.equal(parseBool("0", true), false);
   assert.equal(parseBool(undefined, true), true);
 });
+
+test("new checkout flag can be enabled", () => assert.equal(loadFlags({ FLAG_NEW_CHECKOUT: "on" }).newCheckout, true));
```
